t.script:
var AGENTS = ;
var cav = null, cavCtx = null;

/* Le petit personnage 2D du moteur tour (royaume/duel) : corps + emblème. */
/* Un canvas ne comprend pas « var(--x) » : il faut lui donner une vraie
   couleur. On lit donc la variable dans la feuille de style, avec un repli
   si elle n existe pas. (11/08 : sans ca, addColorStop levait une exception
   et AUCUN avatar n etait dessine.) */
function cssCouleur(nom, repli) {
    try {
        var v = getComputedStyle(document.documentElement)
                    .getPropertyValue(nom);
        v = (v || "").trim();
        return v || repli;
    } catch (e) { return repli; }
}

function dessineAvatar(ctx, embleme, couleur) {
    var b = 0, h = 0;
    ctx.clearRect(0, 0, 120, 120);
    var g = ctx.createLinearGradient(0, 0, 0, 120);
    g.addColorStop(0, cssCouleur("--surface", "#0f172a")); g.addColorStop(1, "#020817");
    ctx.fillStyle = g; ctx.fillRect(0, 0, 120, 120);
    // ombre/sol
    ctx.fillStyle = "rgba(59,130,246,.15)";
    ctx.beginPath(); ctx.ellipse(60, 96, 26, 6, 0, 0, 6.283); ctx.fill();
    // jambes
    ctx.fillStyle = "#1c2438"; ctx.fillRect(50, 84, 7, 9); ctx.fillRect(63, 84, 7, 9);
    // corps
    ctx.fillStyle = couleur; ctx.beginPath(); ctx.roundRect(43, 66, 34, 20, 5); ctx.fill();
    // bras
    ctx.fillStyle = couleur; ctx.fillRect(41, 70, 6, 12); ctx.fillRect(73, 70, 6, 12);
    // tête
    ctx.fillStyle = "#f2c79b"; ctx.beginPath(); ctx.roundRect(49, 48, 22, 20, 6); ctx.fill();
    // cheveux / couvre-chef
    ctx.fillStyle = couleur; ctx.beginPath(); ctx.roundRect(49, 44, 22, 8, 4); ctx.fill();
    // emblème au-dessus
    ctx.fillStyle = cssCouleur("--texte", "#e2e8f0"); ctx.font = "34px system-ui"; ctx.textAlign = "center";
    ctx.fillText(embleme || "🛠️", 60, 34);
    // halo
    ctx.strokeStyle = "rgba(59,130,246,.5)"; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(60, 60, 42, 0, 6.283); ctx.stroke();
}

/* Construit la couleur d'un agent depuis son nom (stable) ou l'emblème. */
function couleurAgent(nom) {
    var palette = [cssCouleur("--primaire", "#3b82f6"), cssCouleur("--ok", "#22c55e"),
                   cssCouleur("--alerte", "#f59e0b"), "#ef4444", "#a855f7",
                   "#06b6d4", "#ec4899", "#84cc16"];
    var s = 0; var n = (nom || "agent");
    for (var i = 0; i < n.length; i++) s = (s + n.charCodeAt(i)) % 997;
    return palette[s % palette.length];
}

function initGalerie() {
    AGENTS.forEach(function (a) {
        var c = document.getElementById("cav-" + a.id);
        if (!c) return;
        var ctx = c.getContext("2d");
        dessineAvatar(ctx, a.embleme, couleurAgent(a.name));
    });
}

/* Ouvre la fiche d'un agent depuis la galerie. */
function openFiche(id) {
    var a = AGENTS.filter(function (x) { return String(x.id) === String(id); })[0];
    if (!a) return;
    document.getElementById("f-emb").textContent = a.embleme;
    document.getElementById("f-nom").textContent = a.name;
    document.getElementById("f-poste").value = a.poste || "";
    document.getElementById("f-poste-txt").textContent = a.poste || "";
    document.getElementById("f-perimetre").value = a.perimetre || "";
    document.getElementById("f-refus").value = a.refus || "";
    document.getElementById("f-consignes").value = a.consignes || "";
    document.getElementById("f-exemples").value = a.exemples || "";
    document.getElementById("f-niv").textContent = "Niv. " + a.niveau + " · " + a.xp + " XP";
    document.getElementById("fiche").classList.add("sur");
    document.getElementById("fiche").querySelector("form").action = "/tour/specs/" + a.id + "/sauver";
    window.scrollTo({ top: 600, behavior: "smooth" });
}
function closeFiche() {
    document.getElementById("fiche").classList.remove("sur");
}
document.addEventListener("DOMContentLoaded", function () {
    initGalerie();
    document.querySelectorAll(".carte").forEach(function (el) {
        el.addEventListener("click", function () { openFiche(el.getAttribute("data-id")); });
    });
    document.getElementById("fiche").querySelector("form")
        .addEventListener("submit", function () { return true; });
});
